template:
// Top-k largest: MIN-heap of size k. O(n log k), O(k) memory, works on a stream.
int kthLargest(const vector<int>& a, int k) {
    priority_queue<int, vector<int>, greater<int>> h;   // min-heap
    for (int x : a) {
        h.push(x);
        if ((int)h.size() > k) h.pop();                // evict the smallest of the k+1
    }
    return h.top();                                    // smallest of the k largest
}

// k most frequent: count, then top-k on (count, value).
vector<int> topKFrequent(const vector<int>& a, int k) {
    unordered_map<int,int> cnt;
    for (int x : a) ++cnt[x];
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> h;  // (count, value), min on count
    for (auto& [v, c] : cnt) { h.push({c, v}); if ((int)h.size() > k) h.pop(); }
    vector<int> out;
    while (!h.empty()) { out.push_back(h.top().second); h.pop(); }
    return out;                                        // ascending by count; reverse if needed
}

// k-way merge: heap of (value, source, position).
vector<int> mergeK(const vector<vector<int>>& lists) {
    using T = tuple<int,int,int>;                      // value, list, index
    priority_queue<T, vector<T>, greater<T>> h;
    for (int i = 0; i < (int)lists.size(); ++i)
        if (!lists[i].empty()) h.push({lists[i][0], i, 0});
    vector<int> out;
    while (!h.empty()) {
        auto [v, i, j] = h.top(); h.pop();
        out.push_back(v);
        if (j + 1 < (int)lists[i].size()) h.push({lists[i][j+1], i, j+1});
    }
    return out;
}

// Running median: two heaps. low = max-heap (smaller half), high = min-heap (larger half).
struct Median {
    priority_queue<int> low;
    priority_queue<int, vector<int>, greater<int>> high;
    void add(int x) {
        low.push(x);                                   // always into low first…
        high.push(low.top()); low.pop();               // …then move low's max across
        if (high.size() > low.size()) { low.push(high.top()); high.pop(); }  // keep |low| >= |high|
    }
    double get() { return low.size() > high.size() ? low.top() : (low.top() + high.top()) / 2.0; }
};
